import React from 'react';
import './Login.css';
import heartImg from '../../assets/heart.png';
import logo from '../../assets/Logo.png';

import { FaUser, FaLock } from 'react-icons/fa';
import { Link } from 'react-router-dom';

const Login = () => {
  return (
    <div className="container-fluid login-container p-0">
      <div className="row min-vh-100">

        {/* Left Side */}
        <div className="col-lg login-left d-flex justify-content-center align-items-center position-relative">
          
          <div className="login-content">

            <h2>Login Page</h2>

            <div className="input-group mb-3 position-relative">
              <input
                type="text"
                className="form-control ps-4"
                placeholder="Username"
              />
              <FaUser className="input-icon" />
            </div>

            <div className="input-group mb-4 position-relative">
              <input
                type="password"
                className="form-control ps-4"
                placeholder="Password"
              />
              <FaLock className="input-icon" />
            </div>

            <button className="btn w-100 btn-gradient mb-3">
              Log In
            </button>

            <div className="register-link text-center">
              Don't have an account?{" "}
              <Link to="/register">Register Now</Link>
            </div>

          </div>

          {/* Shadows */}
          <div className="position-absolute top-0 end-0 w-100 h-100" style={{ pointerEvents: 'none' }}>
            <div className="shadow-top-end"></div>
            <div className="shadow-bottom-start"></div>
          </div>

        </div>


        {/* Middle Gap */}
        <div className="middle-gap"></div>


        {/* Right Side */}
        <div
          className="col-lg-4 login-right"
          style={{
            backgroundImage: `linear-gradient(rgba(0,0,0,0.25), rgba(0,0,0,0.25)), url(${heartImg})`,
          }}
        >
          <div className="logo-title-wrapper">
            <img src={logo} alt="logo" className="logo" />
            <div className="heart-title">
              <h1>Heart Diseases</h1>
            </div>
          </div>
        </div>


      </div>
    </div>
  );
};

export default Login;
